mapper.select:
SELECT o.id, o.domain, o.schema_version, o.status, (SELECT COUNT(*) FROM ontology_entity_type et WHERE et.ontology_id = o.id) AS entity_count, (SELECT COUNT(*) FROM dataset_ontology dn WHERE dn.ontology_id = o.id) AS dataset_count, o.updated_at FROM ontology o
o.status = #{status}
ORDER BY o.id

SELECT COUNT(*) FROM (
  SELECT dn.dataset_id FROM dataset_ontology dn WHERE dn.ontology_id = #{ontologyId}
  UNION
  SELECT dm.dataset_id FROM dataset_mapping dm WHERE dm.ontology_id = #{ontologyId}
) refs

mapper.insert:
INSERT INTO ontology (domain, schema_version, status, updated_at)
VALUES (#{domain}, 1, #{status},
        )
